function histogram(values, bins) {
  const lo = Math.min(...values), hi = Math.max(...values);
  const w = (hi - lo) / bins || 1;
  const counts = new Array(bins).fill(0);
  for (const v of values) counts[Math.min(bins - 1, Math.floor((v - lo) / w))]++;
  return counts.join(',');
}
const bimodal = [1, 1, 2, 2, 9, 9, 10, 10];
console.log('bins5=' + histogram(bimodal, 5));
console.log('bins2=' + histogram(bimodal, 2));
console.log('peaks-stable: ' + (histogram(bimodal, 5).split(',').filter((c) => +c >= 2).length >= 2));

